#include <stdio.h>

int find_index(const int *values, size_t count, int target) {
    for (size_t i = 0; i < count; ++i) if (values[i] == target) return (int)i;
    return -1;
}

int main(void) {
    int values[] = {4, 8, 15, 16};
    printf("index = %d\n", find_index(values, 4, 15));
    return 0;
}
